import JSON

"""
	gen( x, d, y, p, name )

Generate fixture data and write to file.

# Arguments

* `x`: input domain
* `d`: threshold
* `y`: response domain
* `p`: prediction domain
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = Float32.( range( 0.0, stop=50.0, length=503 ) );
julia> d = Float32.( range( 0.0, stop=5.0, length=503 ) );
julia> y = Float32.( range( 0.0, stop=10.0, length=503 ) );
julia> p = Float32.( range( 10.0, stop=0.0, length=503 ) );
julia> gen( x, d, y, p, "data.json" );
```
"""
function gen( x, d, y, p, name )
	x = Float32.( x );
	d = Float32.( d );
	y = Float32.( y );
	p = Float32.( p );

	z = y .- p;
	v = ifelse.(abs.(z) .<= d, .-z .* x, .-d .* sign.(z) .* x);

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("d", d),
		("y", y),
		("p", p),
		("expected", v)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname(file);

# Positive tiny values:
x = Float32.( range( 0.0, stop=20e-20, length=503 ) );
d = Float32.( range( 0.0, stop=5e-20, length=503 ) );
y = Float32.( range( 0.0, stop=10e-20, length=503 ) );
p = Float32.( range( 10e-20, stop=0.0, length=503 ) );
gen( x, d, y, p, "tiny_positive.json" );

# Small positive values:
x = Float32.( range( 0.0, stop=50.0, length=503 ) );
d = Float32.( range( 0.0, stop=5.0, length=503 ) );
y = Float32.( range( 0.0, stop=10.0, length=503 ) );
p = Float32.( range( 10.0, stop=0.0, length=503 ) );
gen( x, d, y, p, "small_positive.json" );

# Negative tiny values:
x = Float32.( range( 0.0, stop=-20e-20, length=503 ) );
d = Float32.( range( 0.0, stop=5e-20, length=503 ) );
y = Float32.( range( -10e-20, stop=0.0, length=503 ) );
p = Float32.( range( 0.0, stop=-10e-20, length=503 ) );
gen( x, d, y, p, "tiny_negative.json" );

# Small negative values:
x = Float32.( range( 0.0, stop=-50.0, length=503 ) );
d = Float32.( range( 0.0, stop=5.0, length=503 ) );
y = Float32.( range( -10.0, stop=0.0, length=503 ) );
p = Float32.( range( 0.0, stop=-10.0, length=503 ) );
gen( x, d, y, p, "small_negative.json" );
